Print this exact marker through a shell command:
PROJECT_A_NEW_SESSION_CAPTURE_TEST
Finish this turn by reporting the repository path, branch, current session ID, Entire status, and any hook warnings. If recording is unavailable, explain the problem before proceeding."""
records=[]
for number,line in enumerate(sys.stdin,1):
    try:
        records.append((number,json.loads(line)))
    except json.JSONDecodeError:
        continue
result={"session_id":"01a11761-440d-7862-8928-ce5db3214385","user_message":[],"shell_output":[],"completed_assistant_response":[],"turn_completion":[]}
for number,record in records:
    payload=record.get("payload",{})
    if record.get("type")=="response_item" and payload.get("type")=="message":
        message="".join(part.get("text","") for part in payload.get("content",[]) if isinstance(part,dict))
        if payload.get("role")=="user" and message==expected_user:
            result["user_message"].append({"line":number,"timestamp":record.get("timestamp"),"role":"user","exact_full_message_match":True,"excerpt":message.splitlines()[0]})
        if payload.get("role")=="assistant" and message.startswith("Entire recording is available and verified.") and message.endswith("Existing code, interview exports, Git history, and checkpoints were preserved."):
            result["completed_assistant_response"].append({"line":number,"timestamp":record.get("timestamp"),"role":"assistant","phase":payload.get("phase"),"excerpt":message.splitlines()[0],"ending":message.splitlines()[-1]})
    item=payload.get("item",{})
    if item.get("type")=="CommandExecution" and item.get("stdout")==marker+"\n":
        result["shell_output"].append({"line":number,"timestamp":record.get("timestamp"),"event":payload.get("type"),"status":item.get("status"),"command":item.get("command"),"stdout":item.get("stdout"),"stderr":item.get("stderr"),"exit_code":item.get("exit_code")})
    if payload.get("type") in ("task_complete","turn_completed"):
        result["turn_completion"].append({"line":number,"timestamp":record.get("timestamp"),"type":payload.get("type"),"turn_id":payload.get("turn_id"),"last_agent_message_excerpt":str(payload.get("last_agent_message",""))[:100]})
result["capture_check_passed"]=all(bool(result[key]) for key in ("user_message","shell_output","completed_assistant_response"))
print(json.dumps(result,indent=2,ensure_ascii=False))'",
  max_output_tokens:5000
}));

